import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"Documentation Map","description":"Hearth documentation structure, recommended reading order, maintenance rules, and publication boundaries.","frontmatter":{"title":"Documentation Map","description":"Hearth documentation structure, recommended reading order, maintenance rules, and publication boundaries.","outline":[2]},"headers":[],"relativePath":"en/reference/source-map.md","filePath":"en/reference/source-map.md","lastUpdated":1794015952000}'),o={name:"en/reference/source-map.md"};function r(s,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="documentation-map" tabindex="-1">Documentation Map <a class="header-anchor" href="#documentation-map" aria-label="Permalink to &quot;Documentation Map&quot;">​</a></h1><p class="lead">All official documentation lives only in `docs/`, and the repository and the live site use the same content. Chinese is the default path; English mirrors the same structure. When you cannot find a category of information, start here to decide which section to read.</p><h2 id="site-structure" tabindex="-1">Site structure <a class="header-anchor" href="#site-structure" aria-label="Permalink to &quot;Site structure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Content</th><th>Entry</th></tr></thead><tbody><tr><td>Design</td><td>1 overall design plus 11 parallel module designs, including technology choices</td><td><a href="/hearth-os/en/design/">Overall design</a></td></tr><tr><td>Delivery</td><td>Six phases, 24 sub-stages, Phase 2–6 delivery status, and real acceptance boundaries</td><td><a href="/hearth-os/en/delivery/">Delivery route</a></td></tr><tr><td>Development log</td><td>Day01–Day04 entries with commits, diffstats, and boundaries</td><td><a href="/hearth-os/en/log/day-04.html">Day04</a></td></tr><tr><td>Appendix</td><td>Engineering, risks, decisions, build-vs-integrate, glossary, checklists, and maintenance material</td><td><a href="/hearth-os/en/reference/">Appendix</a></td></tr><tr><td>Site entry</td><td>Home page and language switch</td><td><a href="/hearth-os/en/">Home</a></td></tr></tbody></table><p>The eleven design modules are Entrances and Experience, Tasks and Durable Execution, Control and Authority, Executors and Routing, Native Agent Runtime, Approvals and External Effects, Runtime and Safety, Memory and Capability Evolution, Evaluation and Cost, Multi-device and Long-running Operation, and Agent Reference Patterns. They are parallel reads, not organized by code directory.</p><p>A first pass can follow &quot;why it exists → what exists now → what is still missing → how it is built&quot;:</p><ol><li>Read the <a href="/hearth-os/en/design/">overall design</a> for product positioning, task flow, technology choices, and module boundaries;</li><li>Read the eleven modules as needed, in any order;</li><li>Check the <a href="/hearth-os/en/delivery/">delivery route</a> for the real state of the six phases: Phase 1 is accepted, while Phases 2–6 have code loops but no real acceptance yet;</li><li>Before continuing development, read <a href="/hearth-os/en/reference/engineering.html">Engineering</a>, <a href="/hearth-os/en/reference/decisions.html">Key decisions</a>, <a href="/hearth-os/en/reference/risks.html">Risks and stop conditions</a>, and the <a href="/hearth-os/en/log/day-04.html">Day04 development log</a>.</li></ol><p>To judge quickly whether the project is worth a longer read, start with &quot;Product positioning and goals&quot; in the overall design and the phase overview in the delivery route. Read the engineering constraints and default checklists before implementing.</p><h2 id="maintenance-and-publication-rules" tabindex="-1">Maintenance and publication rules <a class="header-anchor" href="#maintenance-and-publication-rules" aria-label="Permalink to &quot;Maintenance and publication rules&quot;">​</a></h2><ol><li>Change the Chinese page first, confirm that conclusions, boundaries, and links are accurate, then update the English mirror in the same commit.</li><li>After changing the design or delivery route, check the appendix, navigation, sidebar, home page, and language switch for consistency.</li><li>The design section must not contain code paths, internal class names, or implementation examples; keep engineering constraints in the appendix.</li><li>When removing an old page, take it offline directly without redirects or duplicated bodies; search the whole site for the old path to avoid dead links.</li><li>Run <code>npm run docs:build</code>, then check internal links, mobile width, search, and dark mode.</li><li>Do not use &quot;should&quot; or &quot;later&quot; to hide an undecided point; mark unverified content as an assumption or leave it blank.</li></ol><p>The documentation records implemented code loops, acceptance evidence that exists, and boundaries that are still unverified. Phases 2–6 have runnable code and automated tests, but they are not described as complete without real accounts, real devices, or long-running operation. The development log records each day&#39;s work and commits and does not pretend to be a product release note; formal version numbers and release notes appear only after an installable build exists.</p><p>The live site must match the build output of <code>docs/</code> in the repository. After each publication, check that old addresses are offline, bilingual pages are reachable, and sidebar and home entries point to the correct structure.</p>',12)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
